from bootstrap_environment import Arm64ApptainerEnvironment as Original
class Arm64ApptainerEnvironment(Original):
 async def _start_server(self):
  await super()._start_server()
  result=await self.exec(command="python3 - <<'PY'\nfrom pathlib import Path\nimport re\nfiles=[Path('/etc/apt/sources.list')]+list(Path('/etc/apt/sources.list.d').glob('*.list'))+list(Path('/etc/apt/sources.list.d').glob('*.sources'))\nfor p in files:\n if not p.exists():continue\n text=p.read_text()\n if 'deb.debian.org/debian-security' not in text:continue\n text=text.replace('http://deb.debian.org/debian-security','https://archive.debian.org/debian-security').replace('https://deb.debian.org/debian-security','https://archive.debian.org/debian-security')\n if p.suffix=='.sources':\n  blocks=[]\n  for block in text.split('\\n\\n'):\n   if 'archive.debian.org/debian-security' in block and 'Check-Valid-Until:' not in block:block+='\\nCheck-Valid-Until: no'\n   blocks.append(block)\n  text='\\n\\n'.join(blocks)\n else:\n  lines=[]\n  for line in text.splitlines():\n   if 'archive.debian.org/debian-security' in line and line.startswith('deb ') and '[' not in line:line=line.replace('deb ','deb [check-valid-until=no] ',1)\n   lines.append(line)\n  text='\\n'.join(lines)+'\\n'\n p.write_text(text)\nPY\nrm -rf /var/lib/apt/lists/*\napt-get update",timeout_sec=180)
  if result.return_code != 0:raise RuntimeError("Archive repository failed: "+result.stdout[-2000:]+result.stderr[-1000:])
